-- Remove só a população de demonstração de seed_demo.sql, identificada pelos IDs fixos.
-- Prévia: rode com "rollback;" no lugar do "commit;".
begin;

delete from public.ideas where organization_id in (md5('nuevo-demo:org:vale-claro')::uuid, md5('nuevo-demo:org:ferrolinea')::uuid, md5('nuevo-demo:org:rota-verde')::uuid, md5('nuevo-demo:org:bem-cuidar')::uuid, md5('nuevo-demo:org:ponte-alta')::uuid);
